// assStreamHeader is the ASS prologue dmlive writes before streaming
// Dialogue lines for video (static) danmaku. Byte-identical to Rust dmlive's
// ASS_HEADER_TEXT (including the trailing space after "dmlive").
const assStreamHeader = `[Script Info]
; Script generated by dmlive
; https://github.com/THMonster/Revda
Title: Danmaku file
ScriptType: v4.00+
WrapStyle: 0
ScaledBorderAndShadow: yes
YCbCr Matrix: None
PlayResX: 1920
PlayResY: 1080

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,Sans,40,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,1,0,7,0,0,0,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
`

// float64Atomic is a lock-free float64 cell (this toolchain ships no
// sync/atomic.Float64; bits ride an atomic.Uint64).
type float64Atomic struct {
	v atomic.Uint64
}

func (a *float64Atomic) Load() float64   { return math.Float64frombits(a.v.Load()) }
func (a *float64Atomic) Store(f float64) { a.v.Store(math.Float64bits(f)) }

// DMSettings holds the live-tunable danmaku rendering parameters shared by
// the streaming servers and the keybind handlers.
type DMSettings struct {
	SpeedMS    atomic.Uint64 // danmaku screen-crossing duration, milliseconds
	FontScale  float64Atomic
	FontAlpha  float64Atomic
	RatioScale float64Atomic
	ShowNick   atomic.Bool
	Quiet      atomic.Bool

	// areaPct is how much of the 1080p canvas the scroll lanes may use, and
	// anchor where that area sits (0 top, 1 middle, 2 bottom). Both are fixed
	// for a session.
	areaPct int
	anchor  int
}

// NewDMSettings builds settings with dmlive's config defaults.
func NewDMSettings(speedMS uint64, fontScale, fontAlpha float64, areaPct int, anchor string) *DMSettings {
	s := &DMSettings{}
	if speedMS < 1000 || speedMS > 30000 {
		speedMS = 8000
	}
	s.SpeedMS.Store(speedMS)
	if fontScale <= 0 {
		fontScale = 1.0
	}
	s.FontScale.Store(fontScale)
	if fontAlpha < 0 || fontAlpha > 1 {
		fontAlpha = 0
	}
	s.FontAlpha.Store(fontAlpha)
	s.RatioScale.Store(1.0)
	s.areaPct = clampDanmakuArea(areaPct)
	s.anchor = anchorIndex(anchor)
	return s
}

// FontSize is the current ASS font size (40 * scale).
func (s *DMSettings) FontSize() int {
	return int(40 * s.FontScale.Load())
}

// ChannelNum is the lane count the covered area holds.
func (s *DMSettings) ChannelNum() int {
	return danmakuChannelNum(s.FontSize(), s.areaPct)
}

// LaneY is the top of lane on the 1080p canvas.
func (s *DMSettings) LaneY(lane int) int {
	return danmakuBaseY(s.areaPct, s.anchor) + lane*s.FontSize()
}

// AreaPercent is the covered share of the canvas, for the video renderer.
func (s *DMSettings) AreaPercent() int { return s.areaPct }

// Anchor is "top", "middle" or "bottom", for the video renderer.
func (s *DMSettings) Anchor() string { return anchorName(s.anchor) }

// BGRColor converts a 6-hex RGB color to ASS's &HBBGGRR payload form.
func (s *DMSettings) BGRColor(color string) string {
	if len(color) != 6 { // Rust would panic; fall back to white instead
		color = "ffffff"
	}
	return color[4:6] + color[2:4] + color[0:2]
}

// AlphaHex is the ASS \alpha value (00 opaque .. ff transparent).
func (s *DMSettings) AlphaHex() string {
	return fmt.Sprintf("%02x", uint8(s.FontAlpha.Load()*255))
}

type dmChannel struct {
	length   int
	beginPTS uint64
}

// laneState is the scroll-lane allocator. 30 lanes exist; only the first
// ChannelNum are used, exactly like Rust dmlive.
type laneState struct {
	mu        sync.Mutex
	channels  [30]dmChannel
	readOrder int
}

func (l *laneState) reset() {
	l.mu.Lock()
	defer l.mu.Unlock()
	for i := range l.channels {
		l.channels[i] = dmChannel{}
	}
	l.readOrder = 0
}

// getAvailable returns a free lane index, claiming it on success.
func (l *laneState) getAvailable(s *DMSettings, cPTS uint64, length int) (int, bool) {
	l.mu.Lock()
	defer l.mu.Unlock()
	speed := float64(s.SpeedMS.Load())
	sc := (1920.0 + float64(length)) / speed
	for i := 0; i < s.ChannelNum() && i < len(l.channels); i++ {
		c := &l.channels[i]
		if c.length == 0 {
			c.length = length
			c.beginPTS = cPTS
			return i, true
		}
		if (speed-float64(cPTS)+float64(c.beginPTS))*sc > 1920.0 {
			continue
		}
		if float64(c.length+1920)*(float64(cPTS)-float64(c.beginPTS))/speed < float64(c.length) {
			continue
		}
		c.length = length
		c.beginPTS = cPTS
		return i, true
	}
	return 0, false
}

// displayLength mirrors get_danmaku_display_length: CJK-width approximation
// scaled by the canvas ratio.
func (l *laneState) displayLength(s *DMSettings, nick, text string) int {
	ascii, nonASCII := 0, 0
	for _, c := range text {
		if c < 128 {
			ascii++
		} else {
			nonASCII++
		}
	}
	if s.ShowNick.Load() {
		for _, c := range nick {
			if c < 128 {
				ascii++
			} else {
				nonASCII++
			}
		}
		nonASCII++ // the ": " separator's colon
	}
	fs := float64(s.FontSize())
	return int(math.Round((fs*0.75*float64(nonASCII) + fs*0.50*float64(ascii)) * s.RatioScale.Load()))
}

// LiveDanmaku streams live danmaku as a Matroska flow with two ASS subtitle
// tracks (1 = scroll, 2 = fixed), the wire format mpv and ffmpeg both expect
// from dmlive's danmaku socket.
type LiveDanmaku struct {
	Settings *DMSettings
	fk       *FudujiKiller
	lanes    laneState
}

// NewLiveDanmaku creates the renderer; fk state persists across sessions so
// spam counting survives stream restarts (as in Rust dmlive).
func NewLiveDanmaku(settings *DMSettings) *LiveDanmaku {
	return &LiveDanmaku{Settings: settings, fk: NewFudujiKiller()}
}

// Reset clears lane state between play sessions.
func (l *LiveDanmaku) Reset() {
	l.lanes.reset()
}

// launchSingle renders one message into the cluster. Returns false when the
// message was dropped for having no free lane.
func (l *LiveDanmaku) launchSingle(d *DanmakuMessage, timeMS int64, track byte, cluster *DMKVCluster) bool {
	s := l.Settings
	speed := s.SpeedMS.Load()
	fs := s.FontSize()
	alpha := s.AlphaHex()
	cleanNick := CleanDanmakuText(d.Nick)
	cleanText := CleanDanmakuText(d.Text)
	nickPrefix, sep := "", ""
	if s.ShowNick.Load() {
		nickPrefix, sep = escapeASSText(cleanNick), ": "
	}
	text := escapeASSText(cleanText)

	var ass string
	var dur uint64
	if d.Position == 0 {
		color := d.Color
		if strings.TrimSpace(color) == "" {
			// No color: Rust skips lane allocation entirely and emits the
			// padding block (clients always send a color today).
			ass = fmt.Sprintf("%d,0,Default,dmlive-empty,0,0,0,,", l.nextReadOrder())
			if track == 1 {
				dur = 0
			} else {
				dur = 200
			}
		} else if text == "" {
			return false // emoji-only or punctuation-only: nothing to draw
		} else {
			displayLen := l.lanes.displayLength(s, cleanNick, cleanText)
			lane, ok := l.lanes.getAvailable(s, uint64(timeMS), displayLen)
			if !ok {
				ass = fmt.Sprintf("%d,0,Default,dmlive-empty,0,0,0,,", l.nextReadOrder())
				if track == 1 {
					dur = 0
				} else {
					dur = 200
				}
			} else {
				y := s.LaneY(lane)
				ass = fmt.Sprintf("%d,0,Default,%s,0,0,0,,{\\alpha%s\\fs%d\\1c&%s&\\move(1920,%d,%d,%d)}%s%s%s",
					l.nextReadOrder(), escapeASSText(cleanNick), alpha, fs, s.BGRColor(color), y, -displayLen, y,
					nickPrefix, sep, text)
				dur = speed
			}
		}
	} else {
		if text == "" {
			return false
		}
		ass = fmt.Sprintf("%d,0,Default,%s,0,0,0,,{\\alpha%s\\fs%d\\1c&%s&\\an%d}%s%s%s",
			l.nextReadOrder(), escapeASSText(cleanNick), alpha, fs, s.BGRColor(d.Color), d.Position,
			nickPrefix, sep, text)
		dur = speed
	}
	cluster.AddASSBlock(uint64(timeMS), []byte(ass), dur, track)
	return true
}

func (l *LiveDanmaku) nextReadOrder() int {
	l.lanes.mu.Lock()
	defer l.lanes.mu.Unlock()
	v := l.lanes.readOrder
	l.lanes.readOrder++
	return v
}

// Serve accepts connections on ln (mpv or ffmpeg) until ctx ends, writing
// the MKV header to each and then a continuous cluster flow built from the
// messages channel. A 1 Hz empty-block ticker keeps timestamps advancing.
func (l *LiveDanmaku) Serve(ctx context.Context, ln net.Listener, messages <-chan *DanmakuMessage) error {
	s := l.Settings
	l.Reset()

	var connsMu sync.Mutex
	conns := map[net.Conn]struct{}{}
	broadcast := func(data []byte) {
		connsMu.Lock()
		defer connsMu.Unlock()
		for c := range conns {
			_ = c.SetWriteDeadline(time.Now().Add(5 * time.Second))
			if _, err := c.Write(data); err != nil {
				delete(conns, c)
				_ = c.Close()
			}
		}
	}

	acceptDone := make(chan struct{})
	go func() {
		defer close(acceptDone)
		for {
			c, err := ln.Accept()
			if err != nil {
				return
			}
			if _, err := c.Write(MKVHeader); err != nil {
				_ = c.Close()
				continue
			}
			connsMu.Lock()
			conns[c] = struct{}{}
			connsMu.Unlock()
		}
	}()

	cluster := NewDMKVCluster()
	cluster.Reset(0)
	start := time.Now()
	var padding atomic.Int64
	elapsedMS := func() int64 {
		return time.Since(start).Milliseconds() + padding.Load()
	}

	feedDone := make(chan struct{})
	go func() { // consumer side (Rust t1)
		defer close(feedDone)
		for {
			select {
			case <-ctx.Done():
				return
			case m, ok := <-messages:
				if !ok {
					return
				}
				if !s.Quiet.Load() {
					fmt.Printf("[%s] %s\n", m.Nick, m.Text)
				}
				if !l.fk.DMCheck(m.Text) {
					continue
				}
				l.launchSingle(m, elapsedMS(), 1, cluster)
			}
		}
	}()

	tickerDone := make(chan struct{})
	go func() { // cluster flush side (Rust t2)
		defer close(tickerDone)
		empty := &DanmakuMessage{}
		for i := 0; i < 100; i++ {
			empty.Time = time.UnixMilli(padding.Load())
			l.launchSingle(empty, padding.Load(), 1, cluster)
			l.launchSingle(empty, padding.Load(), 2, cluster)
			padding.Add(1)
		}
		t := time.NewTicker(time.Second)
		defer t.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-t.C:
				nowTS := elapsedMS()
				l.launchSingle(empty, nowTS, 1, cluster)
				l.launchSingle(empty, nowTS, 2, cluster)
				data := cluster.WriteToBytes()
				cluster.Reset(uint64(nowTS))
				broadcast(data)
				padding.Add(1)
			}
		}
	}()

	select {
	case <-ctx.Done():
	case <-feedDone:
	case <-tickerDone:
	}
	// NOTE: ln is owned by the caller (the relay reconnect loop reuses it).
	connsMu.Lock()
	for c := range conns {
		_ = c.Close()
	}
	connsMu.Unlock()
	<-acceptDone
	return nil
}

// ServeStaticASS streams one complete ASS document (bilibili video / baha
// danmaku, positions on the video timeline) to the first connection, then
// closes it — mpv's sub-add and ffmpeg's ass demuxer both read to EOF.
func ServeStaticASS(ctx context.Context, ln net.Listener, msgs []VideoDanmaku, s *DMSettings) error {
	sorted := make([]VideoDanmaku, len(msgs))
	copy(sorted, msgs)
	sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Offset < sorted[j].Offset })

	var b strings.Builder
	b.WriteString(assStreamHeader)

	lanes := &laneState{}
	lanes.reset()
	fs := s.FontSize()
	speed := s.SpeedMS.Load()

	for _, m := range sorted {
		text := CleanDanmakuText(m.Text)
		if text == "" {
			continue
		}
		color := m.Color
		if len(color) != 6 {
			color = "ffffff"
		}
		pos := 0
		if m.Bottom {
			pos = 2
		} else if m.Top {
			pos = 8
		}
		t1 := formatASSTimeOfDay(m.Offset)
		t2 := formatASSTimeOfDay(m.Offset + time.Duration(speed)*time.Millisecond)
		if pos == 0 {
			displayLen := lanes.displayLength(s, "", text)
			lane, ok := lanes.getAvailable(s, uint64(m.Offset.Milliseconds()), displayLen)
			if !ok {
				continue
			}
			y := s.LaneY(lane)
			fmt.Fprintf(&b, "Dialogue: 0,%s,%s,Default,,0,0,0,,{\\alpha%s\\fs%d\\1c&%s&\\move(1920,%d,%d,%d)}%s\n",
				t1, t2, s.AlphaHex(), fs, s.BGRColor(color), y, -displayLen, y, escapeASSText(text))
		} else {
			fmt.Fprintf(&b, "Dialogue: 0,%s,%s,Default,,0,0,0,,{\\alpha%s\\fs%d\\1c&%s&\\an%d}%s\n",
				t1, t2, s.AlphaHex(), fs, s.BGRColor(color), pos, escapeASSText(text))
		}
	}

	c, err := ln.Accept()
	if err != nil {
		return err
	}
	_ = c.SetWriteDeadline(time.Now().Add(30 * time.Second))
	_, werr := c.Write([]byte(b.String()))
	_ = c.Close()
	return werr
}

// formatASSTimeOfDay renders a duration as ASS centiseconds "H:MM:SS.cc"
// (Rust formats with %k:%M:%S%.3f and strips the last millisecond digit).
func formatASSTimeOfDay(d time.Duration) string {
	total := d.Milliseconds()
	if total < 0 {
		total = 0
	}
	cs := (total % 1000) / 10
	sec := total / 1000
	return fmt.Sprintf("%d:%02d:%02d.%02d", sec/3600, (sec/60)%60, sec%60, cs)
}
